import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_tanh(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void cute_tanh_vec4_kernel(const float4* __restrict__ in,
                                       float4* __restrict__ out,
                                       int n4)
{
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    Tensor gIn  = make_tensor(make_gmem_ptr(in),  make_shape(n4));
    Tensor gOut = make_tensor(make_gmem_ptr(out), make_shape(n4));

    for (int idx = tid; idx < n4; idx += stride) {
        float4 v = gIn(idx);
        float4 r;
        r.x = tanhf(v.x);
        r.y = tanhf(v.y);
        r.z = tanhf(v.z);
        r.w = tanhf(v.w);
        gOut(idx) = r;
    }
}

__global__ void cute_tanh_tail_kernel(const float* __restrict__ in,
                                       float* __restrict__ out,
                                       int start,
                                       int n)
{
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int idx = start + tid;

    Tensor gIn  = make_tensor(make_gmem_ptr(in),  make_shape(n));
    Tensor gOut = make_tensor(make_gmem_ptr(out), make_shape(n));

    if (idx < n) {
        gOut(idx) = tanhf(gIn(idx));
    }
}

torch::Tensor cute_tanh(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "expect float32 tensor");

    auto x_c = x.contiguous();
    auto out = torch::empty_like(x_c);

    int64_t n = x_c.numel();
    int64_t n4 = n / 4;
    int64_t tail_start = n4 * 4;
    int64_t tail = n - tail_start;

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    if (n4 > 0) {
        const float4* in_ptr  = reinterpret_cast<const float4*>(x_c.data_ptr<float>());
        float4* out_ptr = reinterpret_cast<float4*>(out.data_ptr<float>());

        int threads = 256;
        int blocks = (int)((n4 + threads - 1) / threads);
        blocks = blocks > 0 ? blocks : 1;

        cute_tanh_vec4_kernel<<<blocks, threads, 0, stream>>>(
            in_ptr, out_ptr, (int)n4);
    }

    if (tail > 0) {
        const float* in_ptr = x_c.data_ptr<float>();
        float* out_ptr = out.data_ptr<float>();

        int threads = 32;
        int blocks = (int)((tail + threads - 1) / threads);
        blocks = blocks > 0 ? blocks : 1;

        cute_tanh_tail_kernel<<<blocks, threads, 0, stream>>>(
            in_ptr, out_ptr, (int)tail_start, (int)n);
    }

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE tanh launch failed");
    return out;
}
"""

cute_ext = load_inline(
    name="cute_tanh_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_tanh"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs a Tanh activation using a custom CUTE kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_tanh(x)


batch_size = 4096
dim = 131072


def get_inputs():
    x = torch.rand(batch_size, dim).cuda()
    return [x]


def get_init_inputs():
    return []

